-- Add only the five remaining Nutrition sections. Run 032 first.
begin;
lock table public.explore_nutrition_content in share row exclusive mode;
do $import$
declare wanted jsonb; incoming public.explore_nutrition_content%rowtype; current_row public.explore_nutrition_content%rowtype;
begin
for wanted in select value from jsonb_array_elements($records$[{"parent_id": "NUT_HOME", "kind": "SECTION", "sort_order": 4, "title": "GF Grains", "educational_state": null, "body": {"intro": null, "safety_note": null, "qualifier": null, "uncertainty_label": null, "visual_asset_id": "VIS_NUT_002", "items": ["Rice", "Corn", "Quinoa", "Buckwheat", "Amaranth", "Millet", "Sorghum", "Teff", "Tapioca/Cassava", "Potato", "Bean flours", "Nut flours", "Gluten-free oats"], "layout": "grid", "item_label": "NATURALLY GF", "item_note": "For grain products, check labeling/source for cross-contact when relevant."}, "source_metadata": {"document": "Nora_Plan_My_C-Day_Explore_From_the_Experts_Coding_Content.docx", "section": "7. Nutrition & Eating Well Mini-Hub", "source_basis": "the uploaded Academy of Nutrition and Dietetics GI Celiac Nutrition Therapy / Label Reading handout supplied by the user, cross-checked against current NIDDK, FDA, and Celiac Disease Foundation guidance. The Academy handout should be treated as a source document, not copied verbatim into the app.", "source_heading": "D. GF Grains — Make This Visual", "original_section_lines": ["Recommended card grid: Rice • Corn • Quinoa • Buckwheat • Amaranth • Millet • Sorghum • Teff • Tapioca/Cassava • Potato • Bean flours • Nut flours • Gluten-free oats.", "Visual recommendation: use original My C-Day illustrations or clean photos of individual grains/foods. Avoid a single green “safe” badge. Each card can say NATURALLY GF plus a small reminder: “For grain products, check labeling/source for cross-contact when relevant.”"]}, "review_status": "APPROVED", "active": true, "content_id": "NUT_004"}, {"parent_id": "NUT_HOME", "kind": "SECTION", "sort_order": 5, "title": "Build a Balanced GF Meal", "educational_state": null, "body": {"intro": null, "safety_note": "App note: this is general nutrition education, not an individualized meal prescription. Teens with allergies, deficiencies, growth concerns, GI symptoms, or other medical needs should use guidance from their clinician/registered dietitian.", "qualifier": null, "uncertainty_label": null, "visual_asset_id": "VIS_NUT_005", "items": ["Choose a naturally gluten-free carbohydrate or grain/starch.", "Add a protein source.", "Add fruit and/or vegetables.", "Include dairy or another appropriate source of calcium when it fits the teen’s diet.", "Use variety across the week rather than trying to make every plate perfect."], "layout": "list", "item_label": null, "item_note": null}, "source_metadata": {"document": "Nora_Plan_My_C-Day_Explore_From_the_Experts_Coding_Content.docx", "section": "7. Nutrition & Eating Well Mini-Hub", "source_basis": "the uploaded Academy of Nutrition and Dietetics GI Celiac Nutrition Therapy / Label Reading handout supplied by the user, cross-checked against current NIDDK, FDA, and Celiac Disease Foundation guidance. The Academy handout should be treated as a source document, not copied verbatim into the app.", "source_heading": "E. Build a Balanced GF Meal", "original_section_lines": ["Do not turn this into calorie tracking or diet culture. Keep it food-positive and flexible.", "Choose a naturally gluten-free carbohydrate or grain/starch.", "Add a protein source.", "Add fruit and/or vegetables.", "Include dairy or another appropriate source of calcium when it fits the teen’s diet.", "Use variety across the week rather than trying to make every plate perfect.", "App note: this is general nutrition education, not an individualized meal prescription. Teens with allergies, deficiencies, growth concerns, GI symptoms, or other medical needs should use guidance from their clinician/registered dietitian."]}, "review_status": "APPROVED", "active": true, "content_id": "NUT_005"}, {"parent_id": "NUT_HOME", "kind": "SECTION", "sort_order": 6, "title": "Label Reading — Teen Version", "educational_state": null, "body": {"intro": null, "safety_note": "U.S. regulatory note: FDA-regulated foods using “gluten-free,” “no gluten,” “free of gluten,” or “without gluten” must meet the FDA rule, including less than 20 ppm gluten.", "qualifier": null, "uncertainty_label": null, "visual_asset_id": null, "items": ["1. Look for a gluten-free claim when relevant.", "2. Read the ingredient list—not just the front of the package.", "3. Know the major gluten-containing grains: wheat, barley, rye, and triticale; watch for malt derived from barley.", "4. Remember that a wheat allergen statement is not a complete gluten check: barley and rye are different grains.", "5. If the answer is still unclear, use “Needs More Information” and check a reliable source or manufacturer instead of guessing."], "layout": "numbered", "item_label": null, "item_note": null}, "source_metadata": {"document": "Nora_Plan_My_C-Day_Explore_From_the_Experts_Coding_Content.docx", "section": "7. Nutrition & Eating Well Mini-Hub", "source_basis": "the uploaded Academy of Nutrition and Dietetics GI Celiac Nutrition Therapy / Label Reading handout supplied by the user, cross-checked against current NIDDK, FDA, and Celiac Disease Foundation guidance. The Academy handout should be treated as a source document, not copied verbatim into the app.", "source_heading": "F. Label Reading — Teen Version", "original_section_lines": ["1. Look for a gluten-free claim when relevant.", "2. Read the ingredient list—not just the front of the package.", "3. Know the major gluten-containing grains: wheat, barley, rye, and triticale; watch for malt derived from barley.", "4. Remember that a wheat allergen statement is not a complete gluten check: barley and rye are different grains.", "5. If the answer is still unclear, use “Needs More Information” and check a reliable source or manufacturer instead of guessing.", "U.S. regulatory note: FDA-regulated foods using “gluten-free,” “no gluten,” “free of gluten,” or “without gluten” must meet the FDA rule, including less than 20 ppm gluten."]}, "review_status": "APPROVED", "active": true, "content_id": "NUT_006"}, {"parent_id": "NUT_HOME", "kind": "SECTION", "sort_order": 7, "title": "Oats", "educational_state": null, "body": {"intro": "Oats are different from wheat, barley, and rye. Most people with celiac disease can tolerate moderate amounts of oats, but oats have a higher cross-contact concern. If you eat oats, choose oats labeled gluten-free and ask your clinician or dietitian what is appropriate for you.", "safety_note": null, "qualifier": null, "uncertainty_label": null, "visual_asset_id": null, "items": [], "layout": "list", "item_label": null, "item_note": null}, "source_metadata": {"document": "Nora_Plan_My_C-Day_Explore_From_the_Experts_Coding_Content.docx", "section": "7. Nutrition & Eating Well Mini-Hub", "source_basis": "the uploaded Academy of Nutrition and Dietetics GI Celiac Nutrition Therapy / Label Reading handout supplied by the user, cross-checked against current NIDDK, FDA, and Celiac Disease Foundation guidance. The Academy handout should be treated as a source document, not copied verbatim into the app.", "source_heading": "G. Oats", "original_section_lines": ["Teen-facing copy: “Oats are different from wheat, barley, and rye. Most people with celiac disease can tolerate moderate amounts of oats, but oats have a higher cross-contact concern. If you eat oats, choose oats labeled gluten-free and ask your clinician or dietitian what is appropriate for you.”", "Important: do NOT import the uploaded handout’s specific 50 g / ¼ cup dry daily limit into My C-Day as a universal teen rule. Current authoritative guidance emphasizes individualized clinician/dietitian advice, and published sources vary in how they discuss quantity."]}, "review_status": "APPROVED", "active": true, "content_id": "NUT_007"}, {"parent_id": "NUT_HOME", "kind": "SECTION", "sort_order": 8, "title": "Nutrients to Know", "educational_state": null, "body": {"intro": "Gluten-free doesn’t automatically mean nutritionally balanced. Celiac disease can affect nutrient absorption, especially around diagnosis, and some packaged GF foods may not replace nutrients found in fortified wheat products.", "safety_note": "Your healthcare team can decide whether you need lab testing or supplements.", "qualifier": null, "uncertainty_label": null, "visual_asset_id": null, "items": ["Fiber", "Iron", "Calcium", "Vitamin D", "Folate and vitamin B12", "Other nutrients may matter depending on the person"], "layout": "list", "item_label": null, "item_note": null}, "source_metadata": {"document": "Nora_Plan_My_C-Day_Explore_From_the_Experts_Coding_Content.docx", "section": "7. Nutrition & Eating Well Mini-Hub", "source_basis": "the uploaded Academy of Nutrition and Dietetics GI Celiac Nutrition Therapy / Label Reading handout supplied by the user, cross-checked against current NIDDK, FDA, and Celiac Disease Foundation guidance. The Academy handout should be treated as a source document, not copied verbatim into the app.", "source_heading": "H. Nutrients to Know", "original_section_lines": ["Teen-facing copy: “Gluten-free doesn’t automatically mean nutritionally balanced. Celiac disease can affect nutrient absorption, especially around diagnosis, and some packaged GF foods may not replace nutrients found in fortified wheat products.”", "Fiber", "Iron", "Calcium", "Vitamin D", "Folate and vitamin B12", "Other nutrients may matter depending on the person", "Do not recommend supplements or doses in the app. Instead: “Your healthcare team can decide whether you need lab testing or supplements.”"]}, "review_status": "APPROVED", "active": true, "content_id": "NUT_008"}]$records$::jsonb) loop
 select * into incoming from jsonb_populate_record(null::public.explore_nutrition_content,wanted);
 select * into current_row from public.explore_nutrition_content where content_id=incoming.content_id for update;
 if found then
  if exists(select 1 from jsonb_each(wanted) f where to_jsonb(current_row)->f.key is distinct from f.value) then raise exception 'Nutrition record differs: %. No changes made.',incoming.content_id; end if;
 else
 insert into public.explore_nutrition_content (parent_id,kind,sort_order,title,educational_state,body,source_metadata,review_status,active,content_id) values (incoming.parent_id,incoming.kind,incoming.sort_order,incoming.title,incoming.educational_state,incoming.body,incoming.source_metadata,incoming.review_status,incoming.active,incoming.content_id);
 end if;
end loop;
end $import$;
commit;
